199				state: url.searchParams.get("state") ?? hashParams.get("state") ?? undefined,
200				error: url.searchParams.get("error") ?? hashParams.get("error") ?? undefined,
201				errorDescription: url.searchParams.get("error_description") ?? hashParams.get("error_description") ?? undefined,
202			};
203		} catch {
204			// Not a URL.
205		}
206		if (value.includes("#")) {
207			const [code, state] = value.split("#", 2);
208			return { code, state };
209		}
210		if (value.includes("code=") || value.includes("state=") || value.includes("error=")) {
211			const params = new URLSearchParams(value.replace(/^\?/, ""));
212			return {
213				code: params.get("code") ?? undefined,
214				state: params.get("state") ?? undefined,
215				error: params.get("error") ?? undefined,
216				errorDescription: params.get("error_description") ?? undefined,
217			};
218		}
219		return { code: value };
220	}
