222	export async function completeOAuthFromInput(input: string): Promise<OAuthCallbackResult> {
223		const parsed = parseOAuthCallbackInput(input);
224		if (parsed.error) {
225			return { success: false, error: parsed.errorDescription ?? parsed.error };
226		}
227		if (!parsed.code) {
228			return { success: false, error: "Paste the final callback URL or authorization code." };
229		}
230		return handleOAuthCallback(parsed.code, parsed.state);
231	}
