233	export async function handleOAuthCallback(code: string, state?: string | null): Promise<OAuthCallbackResult> {
234		const pending = loadPendingOAuth();
235		if (!pending) {
236			return { success: false, error: "No pending OAuth request found. Please try again." };
237		}
238	
239		const age = Date.now() - pending.createdAt;
240		if (age > 10 * 60 * 1000) {
241			clearPendingOAuth();
242			return { success: false, error: "OAuth request expired. Please try again." };
243		}
244	
245		if (state && state !== pending.state) {
246			clearPendingOAuth();
247			return { success: false, error: "OAuth state mismatch. Please try signing in again." };
248		}
249	
250		if (!state && pending.provider === "anthropic") {
251			state = pending.state;
252		}
253	
254		try {
255			const response = await fetch("/api/oauth/token", {
256				method: "POST",
257				headers: { "Content-Type": "application/json" },
258				body: JSON.stringify({
259					provider: pending.provider,
260					code,
261					state: state ?? pending.state,
262					redirect_uri: pending.redirectUri,
263					code_verifier: pending.verifier,
264				}),
265			});
266	
267			if (!response.ok) {
268				const errorBody = await response.text();
269				throw new Error(`Token exchange failed: ${response.status} ${errorBody}`);
270			}
271	
272			const tokens = await response.json();
273	
274			const credentials: OAuthCredentials = {
275				refresh: tokens.refresh_token,
276				access: tokens.access_token,
277				expires: Date.now() + (tokens.expires_in ?? 3600) * 1000,
278				provider: pending.provider,
279				apiKey: typeof tokens.api_key === "string" ? tokens.api_key : undefined,
280				idToken: typeof tokens.id_token === "string" ? tokens.id_token : undefined,
281			};
282	
283			await saveOAuthCredentials(credentials);
284			clearPendingOAuth();
285	
286			return { success: true, provider: pending.provider };
287		} catch (error) {
288			return {
289				success: false,
290				error: error instanceof Error ? error.message : "Unknown error during OAuth",
291			};
292		}
293	}
