301	export async function saveOAuthCredentials(credentials: OAuthCredentials): Promise<void> {
302		const storage = getAppStorage();
303		const key = oauthStorageKey(credentials.provider);
304		await storage.providerKeys.set(key, JSON.stringify(credentials));
305	}
