307	export async function loadOAuthCredentials(provider: OAuthProviderId): Promise<OAuthCredentials | null> {
308		const storage = getAppStorage();
309		const key = oauthStorageKey(provider);
310		const raw = await storage.providerKeys.get(key);
311		if (!raw) return null;
312		try {
313			const parsed = JSON.parse(raw);
314			if (parsed && typeof parsed.refresh === "string" && typeof parsed.access === "string") {
315				return parsed as OAuthCredentials;
316			}
317			return null;
318		} catch {
319			return null;
320		}
321	}
322	
323	export async function deleteOAuthCredentials(provider: OAuthProviderId): Promise<void> {
324		const storage = getAppStorage();
325		const key = oauthStorageKey(provider);
326		await storage.providerKeys.delete(key);
327	}
328	
329	export async function getOAuthAccessToken(provider: OAuthProviderId): Promise<string | null> {
330		const credentials = await loadOAuthCredentials(provider);
331		if (!credentials) return null;
332	
333		if (Date.now() >= credentials.expires - 60_000) {
334			const refreshed = await refreshOAuthToken(provider, credentials);
335			if (!refreshed) return null;
336			return refreshed.apiKey ?? refreshed.access;
337		}
338	
339		return credentials.apiKey ?? credentials.access;
340	}
341	
342	async function refreshOAuthToken(
343		provider: OAuthProviderId,
344		credentials: OAuthCredentials,
345	): Promise<OAuthCredentials | null> {
346		try {
347			const response = await fetch("/api/oauth/refresh", {
348				method: "POST",
349				headers: { "Content-Type": "application/json" },
350				body: JSON.stringify({
351					provider,
352					refresh_token: credentials.refresh,
353				}),
354			});
355	
356			if (!response.ok) {
357				if (response.status === 401 || response.status === 403) {
358					await deleteOAuthCredentials(provider);
359				}
360				return null;
361			}
362	
363			const tokens = await response.json();
364	
365			const newCredentials: OAuthCredentials = {
366				refresh: tokens.refresh_token ?? credentials.refresh,
367				access: tokens.access_token,
368				expires: Date.now() + (tokens.expires_in ?? 3600) * 1000,
369				provider,
370				apiKey: typeof tokens.api_key === "string" ? tokens.api_key : credentials.apiKey,
371				idToken: typeof tokens.id_token === "string" ? tokens.id_token : credentials.idToken,
372			};
373	
374			await saveOAuthCredentials(newCredentials);
375			return newCredentials;
376		} catch {
377			return null;
378		}
379	}
380	
381	export function isOAuthProvider(providerName: string): providerName is OAuthProviderId {
382		return providerName in OAUTH_PROVIDERS;
383	}
384	
385	export function providerToOAuthId(providerName: string): OAuthProviderId | null {
386		if (providerName === "anthropic") return "anthropic";
387		if (providerName === "openai") return "openai-codex";
388		if (providerName === "openai-codex") return "openai-codex";
389		if (providerName === "google") return "google-gemini-cli";
390		return null;
391	}
