  bold: "\x1b[1m",
  dim: "\x1b[2m",
  italic: "\x1b[3m",

  // Primary green — matches web --primary #10b981
  primary: fg(16, 185, 129),
  primaryBg: bg(16, 185, 129) + fg(244, 241, 234),

