1	import { useEffect, useState } from "react";
2	import { getAppStorage } from "@earendil-works/pi-web-ui";
3	import { handleTutorialLinkClick, tutorialApiKeyHref } from "../../lib/tutorial-links";
4	import { promptDioAccess } from "../DioAccessPromptDialog";
5	import {
6		completeOAuthFromInput,
7		initiateOAuth,
8		providerToOAuthId,
9		loadOAuthCredentials,
10		deleteOAuthCredentials,
11		type OAuthProviderId,
12	} from "../../keating/oauth";
13	import { DIO_PROVIDER_ID } from "../../dio-provider";
14	
15	export function CloudProviderKeysSection({ providers }: { providers: string[] }) {
16		return (
17			<div id="settings-section-cloud-providers" className="flex flex-col gap-4 scroll-mt-20">
18				<div>
19					<h3 className="text-sm font-semibold text-foreground mb-2">Cloud Providers</h3>
20					<p className="text-sm text-muted-foreground">
21						Cloud LLM providers with predefined models. API keys are stored locally in your browser.
22					</p>
23				</div>
24				<div className="flex flex-col gap-3">
25					<OAuthProviderKeys providers={providers} />
26				</div>
27			</div>
28		);
29	}
30	
31	function OAuthProviderKeys({ providers }: { providers: string[] }) {
32		const [keys, setKeys] = useState<Record<string, string>>({});
33		const [oauthStatus, setOAuthStatus] = useState<Record<string, boolean>>({});
34		const [oauthLoading, setOauthLoading] = useState<Record<string, boolean>>({});
35		const [oauthInputs, setOAuthInputs] = useState<Record<string, string>>({});
36		const [oauthErrors, setOAuthErrors] = useState<Record<string, string>>({});
37	
38		useEffect(() => {
39			const storage = getAppStorage();
40			Promise.all(providers.map(async (p) => ({
41				provider: p,
42				key: (await storage.providerKeys.get(p)) ?? "",
43			}))).then((results) => {
44				const map: Record<string, string> = {};
45				for (const { provider, key } of results) map[provider] = key;
46				setKeys(map);
47			});
48		}, [providers.join(",")]);
49	
50		useEffect(() => {
51			const checkOAuth = async () => {
52				const storage = getAppStorage();
53				const status: Record<string, boolean> = {};
54				for (const provider of providers) {
55					if (provider === DIO_PROVIDER_ID) {
56						status[provider] = !!(await storage.providerKeys.get(DIO_PROVIDER_ID));
57						continue;
58					}
59					const oauthId = providerToOAuthId(provider);
60					if (oauthId) {
61						const creds = await loadOAuthCredentials(oauthId);
62						status[provider] = !!creds;
63					}
64				}
65				setOAuthStatus(status);
66			};
67			checkOAuth();
68		}, [providers.join(",")]);
69	
70		useEffect(() => {
71			const handler = (event: MessageEvent) => {
72				if (event.data?.type !== "keating-oauth-result") return;
73				const { success, provider: oauthProvider } = event.data;
74				const providerNames = oauthProviderToProviderNames(oauthProvider);
75				if (success && oauthProvider) {
76					setOAuthStatus((prev) => setProviderAliases(prev, providerNames, true));
77					setOAuthInputs((prev) => setProviderAliases(prev, providerNames, ""));
78					setOAuthErrors((prev) => setProviderAliases(prev, providerNames, ""));
79				} else if (providerNames.length > 0) {
80					setOAuthErrors((prev) => setProviderAliases(prev, providerNames, event.data.error ?? "OAuth sign-in failed."));
81				}
82				setOauthLoading((prev) => {
83					const next = { ...prev };
84					for (const k of Object.keys(next)) next[k] = false;
85					return next;
86				});
87			};
88			window.addEventListener("message", handler);
89			return () => window.removeEventListener("message", handler);
90		}, []);
91	
92		const save = async (provider: string, value: string) => {
93			const storage = getAppStorage();
94			if (value.trim()) {
95				await storage.providerKeys.set(provider, value.trim());
96			} else {
97				await storage.providerKeys.delete(provider);
98			}
99		};
100	
101		const handleSignIn = (provider: string) => {
102			if (provider === DIO_PROVIDER_ID) {
103				setOAuthErrors((prev) => ({ ...prev, [provider]: "" }));
104				setOauthLoading((prev) => ({ ...prev, [provider]: true }));
105				void promptDioAccess().then(async (success) => {
106					const hasKey = !!(await getAppStorage().providerKeys.get(DIO_PROVIDER_ID));
107					setOAuthStatus((prev) => ({ ...prev, [provider]: success || hasKey }));
108					setOauthLoading((prev) => ({ ...prev, [provider]: false }));
109					if (!success && !hasKey) {
110						setOAuthErrors((prev) => ({ ...prev, [provider]: "Dio sign-in was not completed." }));
111					}
112				});
113				return;
114			}
115			const oauthId = providerToOAuthId(provider);
116			if (!oauthId) return;
117			setOAuthErrors((prev) => ({ ...prev, [provider]: "" }));
118			setOAuthInputs((prev) => ({ ...prev, [provider]: "" }));
119			setOauthLoading((prev) => ({ ...prev, [provider]: true }));
120			initiateOAuth(oauthId);
121		};
122	
123		const handleCompleteOAuth = async (provider: string) => {
124			const input = oauthInputs[provider]?.trim() ?? "";
125			if (!input) {
126				setOAuthErrors((prev) => ({ ...prev, [provider]: "Paste the callback URL or authorization code first." }));
127				return;
128			}
129			setOauthLoading((prev) => ({ ...prev, [provider]: true }));
130			setOAuthErrors((prev) => ({ ...prev, [provider]: "" }));
131			const result = await completeOAuthFromInput(input);
132			if (result.success && result.provider) {
133				const statusProviders = oauthProviderToProviderNames(result.provider);
134				setOAuthStatus((prev) => setProviderAliases(prev, statusProviders, true));
135				setOAuthInputs((prev) => ({ ...prev, [provider]: "" }));
136			} else {
137				setOAuthErrors((prev) => ({ ...prev, [provider]: result.error ?? "OAuth sign-in failed." }));
138			}
139			setOauthLoading((prev) => ({ ...prev, [provider]: false }));
140		};
141	
142		const handleSignOut = async (provider: string) => {
143			if (provider === DIO_PROVIDER_ID) {
144				const storage = getAppStorage();
145				await storage.providerKeys.delete(DIO_PROVIDER_ID);
146				setOAuthStatus((prev) => ({ ...prev, [provider]: false }));
147				setKeys((prev) => ({ ...prev, [provider]: "" }));
148				return;
149			}
150			const oauthId = providerToOAuthId(provider);
151			if (!oauthId) return;
152			await deleteOAuthCredentials(oauthId);
153			const storage = getAppStorage();
154			await storage.providerKeys.delete(provider);
155			setOAuthStatus((prev) => ({ ...prev, [provider]: false }));
156			setKeys((prev) => ({ ...prev, [provider]: "" }));
157		};
158	
159		const OAUTH_PROVIDER_LABELS: Record<string, string> = {
160			dio: "Dio (Kimi K2.6)",
161			openai: "OpenAI Codex",
162			anthropic: "Anthropic",
163			"openai-codex": "OpenAI Codex",
164			google: "Google Gemini",
165		};
166	
167		return (
168			<>
169				{providers.map((provider) => {
170					const oauthId = providerToOAuthId(provider);
171					const isOAuth = !!oauthId || provider === DIO_PROVIDER_ID;
172					const hasOAuth = oauthStatus[provider] === true;
173					const loading = oauthLoading[provider] === true;
174	
175					if (isOAuth) {
176						return (
177							<div key={provider} className="flex flex-col gap-1">
178								<div className="flex items-center justify-between gap-3">
179									<label className="text-xs font-medium text-muted-foreground capitalize">
180										{OAUTH_PROVIDER_LABELS[provider] ?? provider}
181									</label>
182									<a
183										href={tutorialApiKeyHref(provider)}
184										onClick={(event) => handleTutorialLinkClick(event.nativeEvent, tutorialApiKeyHref(provider))}
185										className="text-xs text-primary underline underline-offset-2"
186									>
187										Get a key
188									</a>
189								</div>
190								{hasOAuth ? (
191									<div className="flex items-center justify-between gap-3 rounded-md border border-border bg-muted/30 px-3 py-2">
192										<span className="text-sm text-muted-foreground">Signed in</span>
193										<button
194											className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2"
195											onClick={() => handleSignOut(provider)}
196										>
197											Sign out
198										</button>
199									</div>
200								) : (
201									<div className="flex flex-col gap-2">
202										<button
203											className="inline-flex items-center justify-center rounded-md bg-primary px-3 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors disabled:opacity-50"
204											disabled={loading}
