1	/**
2	 * Anthropic OAuth flow (Claude Pro/Max)
3	 *
4	 * NOTE: This module uses Node.js http.createServer for the OAuth callback server.
5	 * It is only intended for CLI use, not browser environments.
6	 */
7	import { getProviderEnvValue } from "../provider-env.js";
8	import { oauthErrorHtml, oauthSuccessHtml } from "./oauth-page.js";
9	import { generatePKCE } from "./pkce.js";
10	let nodeApis = null;
11	let nodeApisPromise = null;
12	const decode = (s) => atob(s);
13	const CLIENT_ID = decode("OWQxYzI1MGEtZTYxYi00NGQ5LTg4ZWQtNTk0NGQxOTYyZjVl");
14	const AUTHORIZE_URL = "https://claude.ai/oauth/authorize";
15	const TOKEN_URL = "https://platform.claude.com/v1/oauth/token";
16	const CALLBACK_HOST = getProviderEnvValue("PI_OAUTH_CALLBACK_HOST") || "127.0.0.1";
17	const CALLBACK_PORT = 53692;
18	const CALLBACK_PATH = "/callback";
19	const REDIRECT_URI = `http://localhost:${CALLBACK_PORT}${CALLBACK_PATH}`;
20	const SCOPES = "org:create_api_key user:profile user:inference user:sessions:claude_code user:mcp_servers user:file_upload";
21	async function getNodeApis() {
22	    if (nodeApis)
23	        return nodeApis;
24	    if (!nodeApisPromise) {
25	        if (typeof process === "undefined" || (!process.versions?.node && !process.versions?.bun)) {
26	            throw new Error("Anthropic OAuth is only available in Node.js environments");
27	        }
28	        nodeApisPromise = import("node:http").then((httpModule) => ({
29	            createServer: httpModule.createServer,
30	        }));
31	    }
32	    nodeApis = await nodeApisPromise;
33	    return nodeApis;
34	}
35	function parseAuthorizationInput(input) {
36	    const value = input.trim();
37	    if (!value)
38	        return {};
39	    try {
40	        const url = new URL(value);
41	        return {
42	            code: url.searchParams.get("code") ?? undefined,
43	            state: url.searchParams.get("state") ?? undefined,
44	        };
45	    }
46	    catch {
47	        // not a URL
48	    }
49	    if (value.includes("#")) {
50	        const [code, state] = value.split("#", 2);
51	        return { code, state };
52	    }
53	    if (value.includes("code=")) {
54	        const params = new URLSearchParams(value);
55	        return {
56	            code: params.get("code") ?? undefined,
57	            state: params.get("state") ?? undefined,
58	        };
59	    }
60	    return { code: value };
61	}
62	function formatErrorDetails(error) {
63	    if (error instanceof Error) {
64	        const details = [`${error.name}: ${error.message}`];
65	        const errorWithCode = error;
66	        if (errorWithCode.code)
67	            details.push(`code=${errorWithCode.code}`);
68	        if (typeof errorWithCode.errno !== "undefined")
69	            details.push(`errno=${String(errorWithCode.errno)}`);
70	        if (typeof error.cause !== "undefined") {
71	            details.push(`cause=${formatErrorDetails(error.cause)}`);
72	        }
73	        if (error.stack) {
74	            details.push(`stack=${error.stack}`);
75	        }
76	        return details.join("; ");
77	    }
78	    return String(error);
79	}
80	async function startCallbackServer(expectedState) {
81	    const { createServer } = await getNodeApis();
82	    return new Promise((resolve, reject) => {
83	        let settleWait;
84	        const waitForCodePromise = new Promise((resolveWait) => {
85	            let settled = false;
86	            settleWait = (value) => {
87	                if (settled)
88	                    return;
89	                settled = true;
90	                resolveWait(value);
91	            };
92	        });
93	        const server = createServer((req, res) => {
94	            try {
95	                const url = new URL(req.url || "", "http://localhost");
96	                if (url.pathname !== CALLBACK_PATH) {
97	                    res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
98	                    res.end(oauthErrorHtml("Callback route not found."));
99	                    return;
100	                }
101	                const code = url.searchParams.get("code");
102	                const state = url.searchParams.get("state");
103	                const error = url.searchParams.get("error");
104	                if (error) {
105	                    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
106	                    res.end(oauthErrorHtml("Anthropic authentication did not complete.", `Error: ${error}`));
107	                    return;
108	                }
109	                if (!code || !state) {
110	                    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
111	                    res.end(oauthErrorHtml("Missing code or state parameter."));
112	                    return;
113	                }
114	                if (state !== expectedState) {
115	                    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
116	                    res.end(oauthErrorHtml("State mismatch."));
117	                    return;
118	                }
119	                res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
120	                res.end(oauthSuccessHtml("Anthropic authentication completed. You can close this window."));
121	                settleWait?.({ code, state });
122	            }
123	            catch {
124	                res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
125	                res.end("Internal error");
126	            }
127	        });
128	        server.on("error", (err) => {
129	            reject(err);
130	        });
131	        server.listen(CALLBACK_PORT, CALLBACK_HOST, () => {
132	            resolve({
133	                server,
134	                redirectUri: REDIRECT_URI,
135	                cancelWait: () => {
136	                    settleWait?.(null);
137	                },
138	                waitForCode: () => waitForCodePromise,
139	            });
140	        });
141	    });
142	}
143	async function postJson(url, body) {
144	    const response = await fetch(url, {
145	        method: "POST",
146	        headers: {
147	            "Content-Type": "application/json",
148	            Accept: "application/json",
149	        },
150	        body: JSON.stringify(body),
151	        signal: AbortSignal.timeout(30_000),
152	    });
153	    const responseBody = await response.text();
154	    if (!response.ok) {
155	        throw new Error(`HTTP request failed. status=${response.status}; url=${url}; body=${responseBody}`);
156	    }
157	    return responseBody;
158	}
159	async function exchangeAuthorizationCode(code, state, verifier, redirectUri) {
160	    let responseBody;
161	    try {
162	        responseBody = await postJson(TOKEN_URL, {
163	            grant_type: "authorization_code",
164	            client_id: CLIENT_ID,
165	            code,
166	            state,
167	            redirect_uri: redirectUri,
168	            code_verifier: verifier,
169	        });
170	    }
171	    catch (error) {
172	        throw new Error(`Token exchange request failed. url=${TOKEN_URL}; redirect_uri=${redirectUri}; response_type=authorization_code; details=${formatErrorDetails(error)}`);
173	    }
174	    let tokenData;
175	    try {
176	        tokenData = JSON.parse(responseBody);
177	    }
178	    catch (error) {
179	        throw new Error(`Token exchange returned invalid JSON. url=${TOKEN_URL}; body=${responseBody}; details=${formatErrorDetails(error)}`);
180	    }
181	    return {
182	        refresh: tokenData.refresh_token,
183	        access: tokenData.access_token,
184	        expires: Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000,
185	    };
186	}
187	/**
188	 * Login with Anthropic OAuth (authorization code + PKCE)
189	 */
190	export async function loginAnthropic(options) {
191	    const { verifier, challenge } = await generatePKCE();
192	    const server = await startCallbackServer(verifier);
193	    let code;
194	    let state;
195	    let redirectUriForExchange = REDIRECT_URI;
196	    try {
197	        const authParams = new URLSearchParams({
198	            code: "true",
199	            client_id: CLIENT_ID,
200	            response_type: "code",
201	            redirect_uri: REDIRECT_URI,
202	            scope: SCOPES,
203	            code_challenge: challenge,
204	            code_challenge_method: "S256",
205	            state: verifier,
206	        });
207	        options.onAuth({
208	            url: `${AUTHORIZE_URL}?${authParams.toString()}`,
209	            instructions: "Complete login in your browser. If the browser is on another machine, paste the final redirect URL here.",
210	        });
211	        if (options.onManualCodeInput) {
212	            let manualInput;
213	            let manualError;
214	            const manualPromise = options
215	                .onManualCodeInput()
216	                .then((input) => {
217	                manualInput = input;
218	                server.cancelWait();
219	            })
220	                .catch((err) => {
221	                manualError = err instanceof Error ? err : new Error(String(err));
222	                server.cancelWait();
223	            });
224	            const result = await server.waitForCode();
225	            if (manualError) {
226	                throw manualError;
227	            }
228	            if (result?.code) {
229	                code = result.code;
230	                state = result.state;
231	                redirectUriForExchange = REDIRECT_URI;
232	            }
233	            else if (manualInput) {
234	                const parsed = parseAuthorizationInput(manualInput);
235	                if (parsed.state && parsed.state !== verifier) {
236	                    throw new Error("OAuth state mismatch");
237	                }
238	                code = parsed.code;
239	                state = parsed.state ?? verifier;
240	            }
241	            if (!code) {
242	                await manualPromise;
243	                if (manualError) {
244	                    throw manualError;
245	                }
246	                if (manualInput) {
247	                    const parsed = parseAuthorizationInput(manualInput);
248	                    if (parsed.state && parsed.state !== verifier) {
249	                        throw new Error("OAuth state mismatch");
250	                    }
251	                    code = parsed.code;
252	                    state = parsed.state ?? verifier;
253	                }
254	            }
255	        }
256	        else {
257	            const result = await server.waitForCode();
258	            if (result?.code) {
259	                code = result.code;
260	                state = result.state;
261	                redirectUriForExchange = REDIRECT_URI;
262	            }
263	        }
264	        if (!code) {
265	            const input = await options.onPrompt({
266	                message: "Paste the authorization code or full redirect URL:",
267	                placeholder: REDIRECT_URI,
268	            });
269	            const parsed = parseAuthorizationInput(input);
270	            if (parsed.state && parsed.state !== verifier) {
271	                throw new Error("OAuth state mismatch");
272	            }
273	            code = parsed.code;
274	            state = parsed.state ?? verifier;
275	        }
276	        if (!code) {
277	            throw new Error("Missing authorization code");
278	        }
279	        if (!state) {
280	            throw new Error("Missing OAuth state");
281	        }
282	        options.onProgress?.("Exchanging authorization code for tokens...");
283	        return exchangeAuthorizationCode(code, state, verifier, redirectUriForExchange);
284	    }
285	    finally {
286	        server.server.close();
287	    }
288	}
289	/**
290	 * Refresh Anthropic OAuth token
291	 */
292	export async function refreshAnthropicToken(refreshToken) {
293	    let responseBody;
294	    try {
295	        responseBody = await postJson(TOKEN_URL, {
296	            grant_type: "refresh_token",
297	            client_id: CLIENT_ID,
298	            refresh_token: refreshToken,
299	        });
300	    }
301	    catch (error) {
302	        throw new Error(`Anthropic token refresh request failed. url=${TOKEN_URL}; details=${formatErrorDetails(error)}`);
303	    }
304	    let data;
305	    try {
306	        data = JSON.parse(responseBody);
307	    }
308	    catch (error) {
309	        throw new Error(`Anthropic token refresh returned invalid JSON. url=${TOKEN_URL}; body=${responseBody}; details=${formatErrorDetails(error)}`);
310	    }
311	    return {
312	        refresh: data.refresh_token,
313	        access: data.access_token,
314	        expires: Date.now() + data.expires_in * 1000 - 5 * 60 * 1000,
315	    };
316	}
317	export const anthropicOAuth = {
318	    name: "Anthropic (Claude Pro/Max)",
319	    async login(callbacks) {
320	        // The manual_code prompt races the local callback server; abort it once
321	        // the flow settles so the UI can dismiss the pending input.
322	        const manualAbort = new AbortController();
323	        try {
324	            const credentials = await loginAnthropic({
325	                onAuth: (info) => callbacks.notify({ type: "auth_url", url: info.url, instructions: info.instructions }),
326	                onProgress: (message) => callbacks.notify({ type: "progress", message }),
327	                onPrompt: (prompt) => callbacks.prompt({ type: "text", message: prompt.message, placeholder: prompt.placeholder }),
328	                onManualCodeInput: () => callbacks.prompt({
329	                    type: "manual_code",
330	                    message: "Complete login in your browser, or paste the authorization code / redirect URL here:",
331	                    placeholder: REDIRECT_URI,
332	                    signal: manualAbort.signal,
333	                }),
334	            });
335	            return { ...credentials, type: "oauth" };
336	        }
337	        finally {
338	            manualAbort.abort();
339	        }
340	    },
341	    async refresh(credential) {
342	        return { ...(await refreshAnthropicToken(credential.refresh)), type: "oauth" };
343	    },
344	    async toAuth(credential) {
345	        return { apiKey: credential.access };
346	    },
347	};
348	export const anthropicOAuthProvider = {
349	    id: "anthropic",
350	    name: "Anthropic (Claude Pro/Max)",
351	    usesCallbackServer: true,
352	    async login(callbacks) {
353	        return loginAnthropic({
354	            onAuth: callbacks.onAuth,
355	            onPrompt: callbacks.onPrompt,
356	            onProgress: callbacks.onProgress,
357	            onManualCodeInput: callbacks.onManualCodeInput,
358	        });
359	    },
360	    async refreshToken(credentials) {
361	        return refreshAnthropicToken(credentials.refresh);
362	    },
363	    getApiKey(credentials) {
364	        return credentials.access;
365	    },
366	};
